DROP TABLE IF EXISTS `md_expense_standard`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `md_expense_standard` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL COMMENT '租户ID【多租户隔离字段】',
  `std_code` varchar(64) NOT NULL COMMENT '标准编码',
  `std_name` varchar(200) NOT NULL COMMENT '标准名称',
  `item_id` bigint NOT NULL COMMENT '费用项目ID',
  `post_level_min` int DEFAULT NULL COMMENT '适用职级下限,空表示不限',
  `post_level_max` int DEFAULT NULL COMMENT '适用职级上限,空表示不限',
  `city_level` varchar(20) DEFAULT NULL COMMENT '适用城市级别,空表示不限',
  `company_id` bigint DEFAULT NULL COMMENT '适用公司,空表示全租户',
  `std_type` varchar(20) NOT NULL DEFAULT 'DAY' COMMENT '标准类型:DAY每日限额/TIMES每次限额/PERSON人均限额/MONTH每月限额',
  `amount` decimal(20,2) NOT NULL DEFAULT '0.00' COMMENT '限额金额',
  `currency_code` varchar(10) NOT NULL DEFAULT 'CNY' COMMENT '币种',
  `control_type` varchar(20) NOT NULL DEFAULT 'WARN' COMMENT '控制方式:WARN提醒/BLOCK禁止',
  `effect_date` date DEFAULT NULL COMMENT '生效日期',
  `expire_date` date DEFAULT NULL COMMENT '失效日期',
  `priority` int NOT NULL DEFAULT '0' COMMENT '优先级,数值大者优先',
  `status` varchar(20) NOT NULL DEFAULT 'NORMAL' COMMENT '状态:NORMAL/DISABLED',
  `remark` varchar(500) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  `abroad` tinyint NOT NULL DEFAULT '0' COMMENT '1=境外标准档',
  `country_tier` varchar(32) DEFAULT NULL COMMENT '国家档位：DEV(发达)/EMG(新兴)/OTH，NULL=通用',
  `allowance_daily` decimal(20,2) DEFAULT NULL COMMENT '补贴/日（本位币）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_std_code` (`tenant_id`,`std_code`),
  KEY `idx_tenant` (`tenant_id`),
  KEY `idx_tenant_item` (`tenant_id`,`item_id`)
) ENGINE=InnoDB AUTO_INCREMENT=532 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='费用标准';
/*!40101 SET character_set_client = @saved_cs_client */;

